use verus::*;

fn char_to_val(c: char) -> u8 {
    // Convert a hex char in ['A'..='F'] to 10..15
    match c {
        'A' => 10,
        'B' => 11,
        'C' => 12,
        'D' => 13,
        'E' => 14,
        'F' => 15,
        _ => 0, // unreachable due to precondition
    }
}

#[verus::verus]
fn solve(stdin_input: Vec<char>) -> Vec<char> {
    // Preconditions:
    // stdin_input length is either 3 or 4
    // stdin_input[1] == ' '
    // first and third chars in ['A'..'F']
    // if length == 4, stdin_input[3] == '\n'
    require(
        (stdin_input.len() == 3 || stdin_input.len() == 4) &&
        stdin_input[1] == ' ' &&
        ('A' <= stdin_input[0] && stdin_input[0] <= 'F') &&
        ('A' <= stdin_input[2] && stdin_input[2] <= 'F') &&
        (stdin_input.len() != 4 || stdin_input[3] == '\n')
    );

    let x = stdin_input[0];
    let y = stdin_input[2];

    let x_val = char_to_val(x);
    let y_val = char_to_val(y);

    let res_char = if x_val < y_val {
        '<'
    } else if x_val == y_val {
        '='
    } else {
        '>'
    };

    // The output is [res_char, '\n']
    let result = vec![res_char, '\n'];

    // Postcondition: output length 2, second is '\n',
    // first char correctly reflects comparison of x and y
    ensures(result.len() == 2);
    ensures(result[1] == '\n');
    ensures(
        (x_val < y_val && result[0] == '<') ||
        (x_val == y_val && result[0] == '=') ||
        (x_val > y_val && result[0] == '>')
    );

    result
}